    if (burstOf(strength, float(k)) < 0.5) continue;
    vec2 source = tornCell(cell, strength, float(k));
    if (part == k && inTearBlock(cell, float(k))) return clamp(source + vec2(0.0, floor(gGrid.y * 0.06)), vec2(0.0), gGrid - 1.0);
