  if (isFilter(f, 6.0) || isFilter(f, 13.0)) {
    vec3 sum = vec3(0.0);
    for (int k = 0; k < 8; k++) {
      float t = float(k) * 0.785398;
      vec3 s = rgbAt(cell + floor(vec2(cos(t), sin(t)) * 2.5 + 0.5));
      sum += s * smoothstep(0.45, 0.9, lumaOf(s));
    }
    o = c + sum * 0.22;
